<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('project_tasks.view');$pdo=db();$projectId=(int)($_GET['project_id']??0);$project=$projectId?pm_fetch_project($pdo,$projectId):null;$pageTitle=$project?'Kanban · '.$project['name']:'Kanban de proyectos';$projects=pm_project_options($pdo);$where=$projectId?'WHERE t.project_id=?':'';$s=$pdo->prepare("SELECT t.*,p.name project_name,p.color project_color,u.name assigned_name,m.name milestone_name FROM project_tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN users u ON u.id=t.assigned_to LEFT JOIN project_milestones m ON m.id=t.milestone_id $where ORDER BY t.sort_order,t.due_date IS NULL,t.due_date,t.id");$s->execute($projectId?[$projectId]:[]);$tasks=$s->fetchAll();$statuses=['backlog','todo','in_progress','review','blocked','done'];$by=[];foreach($statuses as$x)$by[$x]=[];foreach($tasks as$t)$by[$t['status']][]=$t;require __DIR__.'/includes/header.php';if($project)echo pm_project_tabs($projectId,'kanban');?>
<div class="project-hero compact"><div><span class="eyebrow">KANBAN</span><h2><?=e($project?$project['name']:'Todos los proyectos')?></h2><p>Arrastra las tareas entre columnas para actualizar el estado y el avance.</p></div><div class="actions"><?php if(has_permission('project_tasks.manage')):?><a class="btn btn-primary" href="project_task_form.php<?=$projectId?'?project_id='.$projectId:''?>">+ NUEVA TAREA</a><?php endif;?><form method="get"><select name="project_id" onchange="this.form.submit()"><option value="0">Todos los proyectos</option><?php foreach($projects as$p):?><option value="<?=$p['id']?>" <?=$projectId===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></form></div></div>
<div class="pm-kanban" data-pm-kanban data-move-url="project_task_action.php"><?php foreach($statuses as$status):?><section class="pm-kanban-column" data-pm-status="<?=$status?>"><header><div><h3><?=e(pm_task_status_label($status))?></h3><small><?=count($by[$status])?> tareas</small></div><span class="pm-kanban-dot status-<?=$status?>"></span></header><div class="pm-kanban-drop" data-pm-dropzone="<?=$status?>"><?php foreach($by[$status] as$t):?><article class="pm-task-card priority-<?=e($t['priority'])?>" draggable="<?=has_permission('project_tasks.manage')?'true':'false'?>" data-pm-task="<?=$t['id']?>"><div class="pm-task-card-top"><span class="pm-project-chip" style="--project-color:<?=e($t['project_color'])?>"><?=e($t['project_name'])?></span><?=pm_badge($t['priority'],'priority')?></div><h4><a href="project_task_form.php?id=<?=$t['id']?>"><?=e($t['title'])?></a></h4><?php if($t['milestone_name']):?><p><?=e($t['milestone_name'])?></p><?php endif;?><div class="pm-progress"><span style="width:<?=(int)$t['progress']?>%"></span></div><footer><span><?=crm_icon('users')?> <?=e($t['assigned_name']?:'Sin asignar')?></span><span class="<?=$t['due_date']&&$t['status']!=='done'&&$t['due_date']<date('Y-m-d')?'overdue':''?>"><?=crm_icon('calendar')?> <?=e(pm_date($t['due_date']))?></span></footer></article><?php endforeach;?></div></section><?php endforeach;?></div>
<script src="assets/js/project-manager.js?v=2.0.0"></script><?php require __DIR__.'/includes/footer.php';?>
